package com.example.waqt

import android.app.admin.DevicePolicyManager
import android.content.ComponentName
import android.content.Context
import android.content.Intent
import android.os.Build
import android.provider.Settings 

// This class implements the interface generated by Pigeon
class ScreenLockApiImpl(private val context: Context) : ScreenLockApi {
    private val adminComponent = ComponentName(context, MyDeviceAdminReceiver::class.java)

    override fun checkLockPermission(): Boolean {
        return ScreenLockService.instance != null
    }

    override fun openAccessibilitySettings() {
        val intent = Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS).apply {
            // FLAG_ACTIVITY_NEW_TASK is required when starting an Activity from a non-Activity context
            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        }
        context.startActivity(intent)
    }

    override fun lockScreen() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            val service = ScreenLockService.instance
            if (service != null) {
                service.lockDevice()
            } else {
                throw ScreenLockError("NOT_ENABLED", "Accessibility service not enabled", null)
            }
        } else {
            throw ScreenLockError("UNSUPPORTED", "Requires Android 9.0+", null)
        }
    }


    /// theses two was created in  past, check issue #12
    override fun lockScreenAdmin() {
        val devicePolicyManager = 
            context.getSystemService(Context.DEVICE_POLICY_SERVICE) as DevicePolicyManager

        if (devicePolicyManager.isAdminActive(adminComponent)) {
            devicePolicyManager.lockNow()
        } else {
            throw FlutterError("NOT_ADMIN", "Device admin not enabled", null)
        }
    }

    /// theses two was created in  past, check issue #12
    override fun requestLockPermission() {
        val intent = Intent(DevicePolicyManager.ACTION_ADD_DEVICE_ADMIN).apply {
            putExtra(DevicePolicyManager.EXTRA_DEVICE_ADMIN, adminComponent)
            putExtra(
                DevicePolicyManager.EXTRA_ADD_EXPLANATION,
                "Allow this app to lock the screen on double tap."
            )
            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        }
        context.startActivity(intent)
    }
}
